//! Audio track planning, synthesis and mixing.
//!
//! The mixer consumes a neutral [`AudioPlan`]: an explicit sample rate,
//! channel count, duration and placements in project frames. It knows nothing
//! about scenes — the scene audio bed IR is lowered into a plan by the caller.
//!
//! The BGM and every sound effect are generated by this code — no sample
//! files, no external tools. Narration is a reserved slot: if the plan points
//! at a PCM WAV file it is decoded and mixed in; otherwise the slot stays
//! silent. Sample rate and channels are input contracts: nothing is resampled
//! implicitly between synthesis and the written buffer.

use media_codec::MediaLibrary;
use media_codec::parse_wav_pcm16;
use media_types::Error;
use media_types::hash;

/// One synthesized effect placed on the track.
#[derive(Clone, Debug)]
pub struct SfxPlacement {
    pub kind: String,
    pub at_frames: u32,
    pub volume: f32,
}

/// One imported audio file placed at `at_frames`, playing from `offset_frames`.
#[derive(Clone, Debug)]
pub struct ClipPlacement {
    pub src: String,
    pub at_frames: u32,
    /// Length in frames; `None` means "until the file ends".
    pub duration_frames: Option<u32>,
    /// Source offset in frames skipped before playback starts.
    pub offset_frames: u32,
    pub volume: f32,
}

/// The reserved narration slot: a PCM16 WAV mixed in at a frame offset.
#[derive(Clone, Debug)]
pub struct NarrationPlacement {
    pub wav: String,
    pub delay_frames: u32,
    pub volume: f32,
}

/// Background music bed parameters.
#[derive(Clone, Debug)]
pub struct BgmPlan {
    pub volume: f32,
    /// Reserved for future moods; only `pad` exists today.
    pub mood: String,
}

/// Neutral audio track plan: the mixer's only input contract.
///
/// Placements are expressed in project frames, the output format in explicit
/// sample rate and channels, and the bed length in frames. The plan never
/// carries seconds: that value is derived, so it cannot contradict the others.
#[derive(Clone, Debug)]
pub struct AudioPlan {
    pub sample_rate: u32,
    pub channels: u16,
    pub fps: u32,
    pub duration_frames: u32,
    pub bgm: Option<BgmPlan>,
    pub narration: Option<NarrationPlacement>,
    pub sfx: Vec<SfxPlacement>,
    pub clips: Vec<ClipPlacement>,
}

/// Builds the full audio bed: synthesized BGM and effects, the reserved
/// narration slot, and every imported audio clip placed on the timeline.
pub fn build_audio(plan: &AudioPlan, media: &mut MediaLibrary) -> Result<Vec<i16>, Error> {
    if plan.channels != 2 {
        return Err(Error::invalid_input(format!("the mixer is stereo-only, got {} channels", plan.channels)));
    }
    if plan.sample_rate == 0 || plan.fps == 0 {
        return Err(Error::invalid_input("sample_rate and fps must be positive"));
    }
    let frames = (plan.duration_frames as f64 / plan.fps as f64 * plan.sample_rate as f64).ceil() as usize;
    let mut buf = vec![0f32; frames * 2];

    if let Some(bgm) = &plan.bgm {
        synth_pad(&mut buf, bgm.volume, plan.sample_rate);
        synth_plucks(&mut buf, bgm.volume * 0.5, plan.sample_rate);
    }
    for sfx in &plan.sfx {
        let seconds = sfx.at_frames as f64 / plan.fps as f64;
        match sfx.kind.as_str() {
            "whoosh" => whoosh(&mut buf, seconds, sfx.volume, plan.sample_rate),
            "tick" => tick(&mut buf, seconds, sfx.volume, plan.sample_rate),
            "impact" => impact(&mut buf, seconds, sfx.volume, plan.sample_rate),
            "riser" => riser(&mut buf, seconds, sfx.volume, plan.sample_rate),
            "glitch" => glitch(&mut buf, seconds, sfx.volume, plan.sample_rate),
            "sub" => sub_drop(&mut buf, seconds, sfx.volume, plan.sample_rate),
            _ => {}
        }
    }
    if let Some(narration) = &plan.narration {
        mix_wav(&mut buf, &narration.wav, narration.delay_frames, narration.volume, plan)?;
    }
    for clip in &plan.clips {
        // A missing or undecodable import must not abort the render: the
        // clip stays silent and the rest of the film still compiles.
        let Ok(samples) = media.audio_pcm(&clip.src, plan.sample_rate) else {
            continue;
        };
        let start = (clip.at_frames as f64 / plan.fps as f64 * plan.sample_rate as f64) as usize;
        let offset = (clip.offset_frames as f64 / plan.fps as f64 * plan.sample_rate as f64) as usize;
        let limit =
            clip.duration_frames.map(|d| (d as f64 / plan.fps as f64 * plan.sample_rate as f64) as usize).unwrap_or(usize::MAX);
        let total = frames_len(&buf);
        for i in 0..limit {
            let Some(sample) = samples.get(offset + i) else {
                break;
            };
            let Some(at) = start.checked_add(i) else {
                break;
            };
            if at >= total {
                break;
            }
            buf[at * 2] += sample[0] * clip.volume;
            buf[at * 2 + 1] += sample[1] * clip.volume;
        }
    }

    Ok(buf.into_iter().map(|s| (s.clamp(-1.0, 1.0) * 32767.0) as i16).collect())
}

fn frames_len(buf: &[f32]) -> usize {
    buf.len() / 2
}

/// Slow chord pad: four chords cycling, two detuned partials each.
fn synth_pad(buf: &mut [f32], volume: f32, sample_rate: u32) {
    // A minor bed: Am, F, C, G — root frequencies.
    let chords = [[110.0, 164.81, 220.0], [87.31, 130.81, 174.61], [130.81, 164.81, 196.0], [98.0, 123.47, 146.83]];
    let chord_seconds = 8.0;
    for i in 0..frames_len(buf) {
        let t = i as f64 / sample_rate as f64;
        let chord = &chords[((t / chord_seconds) as usize) % chords.len()];
        let phase_in_chord = (t % chord_seconds) / chord_seconds;
        let env = (phase_in_chord * std::f64::consts::PI).sin().powf(0.6);
        let mut s = 0.0f64;
        for f in chord {
            let w = *f * t * std::f64::consts::TAU;
            s += w.sin() * 0.5 + (w * 2.0).sin() * 0.12;
            let detuned = (*f * 1.003) * t * std::f64::consts::TAU;
            s += detuned.sin() * 0.35;
        }
        let value = (s / (chord.len() as f64 * 1.2)) * env * volume as f64;
        // Gentle stereo width via alternating polarity of the detune.
        buf[i * 2] += value as f32;
        buf[i * 2 + 1] += value as f32 * 0.92;
    }
}

/// Sparse pentatonic plucks seeded deterministically.
fn synth_plucks(buf: &mut [f32], volume: f32, sample_rate: u32) {
    let scale = [440.0, 523.25, 587.33, 659.25, 783.99];
    let total = frames_len(buf);
    let mut slot = 0usize;
    let mut cursor = (sample_rate as usize) * 3; // start after 3s
    while cursor < total {
        let seed = hash(slot as u32);
        let note = scale[(seed % scale.len() as u32) as usize];
        let decay_seconds = 1.6;
        let len = ((decay_seconds * sample_rate as f64) as usize).min(total - cursor);
        for i in 0..len {
            let t = i as f64 / sample_rate as f64;
            let env = (-t * 3.2).exp();
            let s = (note * t * std::f64::consts::TAU).sin() * 0.7 + (note * 2.0 * t * std::f64::consts::TAU).sin() * 0.2;
            let v = (s * env * volume as f64 * 0.5) as f32;
            buf[(cursor + i) * 2] += v;
            buf[(cursor + i) * 2 + 1] += v * 0.9;
        }
        slot += 1;
        let gap = 2.0 + (hash(slot as u32 * 7 + 13) % 40) as f64 / 10.0;
        cursor += (gap * sample_rate as f64) as usize;
    }
}

/// Filtered noise sweep for scene transitions.
fn whoosh(buf: &mut [f32], at_seconds: f64, volume: f32, sample_rate: u32) {
    let start = (at_seconds * sample_rate as f64) as usize;
    let len = (0.55 * sample_rate as f64) as usize;
    let total = frames_len(buf);
    let mut seed = (start as u32) | 0x9e37;
    let mut low = 0.0f32;
    for i in 0..len {
        if start + i >= total {
            break;
        }
        let t = i as f32 / len as f32;
        let env = (t * std::f32::consts::PI).sin().powf(1.5);
        seed = hash(seed);
        let noise = (seed as f32 / u32::MAX as f32) * 2.0 - 1.0;
        low += (noise - low) * (0.02 + t * 0.25);
        let v = low * env * volume;
        buf[(start + i) * 2] += v;
        buf[(start + i) * 2 + 1] += v * 0.95;
    }
}

/// Short high blip for counters and list ticks.
fn tick(buf: &mut [f32], at_seconds: f64, volume: f32, sample_rate: u32) {
    let start = (at_seconds * sample_rate as f64) as usize;
    let len = (0.06 * sample_rate as f64) as usize;
    let total = frames_len(buf);
    for i in 0..len {
        if start + i >= total {
            break;
        }
        let t = i as f64 / sample_rate as f64;
        let env = (-t * 60.0).exp();
        let s = (1320.0 * t * std::f64::consts::TAU).sin() * env * volume as f64 * 0.5;
        buf[(start + i) * 2] += s as f32;
        buf[(start + i) * 2 + 1] += s as f32;
    }
}

/// Low thud for emphasis moments.
fn impact(buf: &mut [f32], at_seconds: f64, volume: f32, sample_rate: u32) {
    let start = (at_seconds * sample_rate as f64) as usize;
    let len = (0.35 * sample_rate as f64) as usize;
    let total = frames_len(buf);
    for i in 0..len {
        if start + i >= total {
            break;
        }
        let t = i as f64 / sample_rate as f64;
        let env = (-t * 9.0).exp();
        let s = (72.0 * t * std::f64::consts::TAU).sin() * env * volume as f64;
        buf[(start + i) * 2] += s as f32;
        buf[(start + i) * 2 + 1] += s as f32;
    }
}

/// Rising filtered noise, used to build tension into a cut.
fn riser(buf: &mut [f32], at_seconds: f64, volume: f32, sample_rate: u32) {
    let start = (at_seconds * sample_rate as f64) as usize;
    let len = (1.6 * sample_rate as f64) as usize;
    let total = frames_len(buf);
    let mut seed = (start as u32) | 0x5f37;
    let mut low = 0.0f32;
    for i in 0..len {
        if start + i >= total {
            break;
        }
        let t = i as f32 / len as f32;
        seed = hash(seed);
        let noise = (seed as f32 / u32::MAX as f32) * 2.0 - 1.0;
        // The filter opens up as the riser climbs.
        low += (noise - low) * (0.01 + t * t * 0.5);
        let env = t * t;
        let v = low * env * volume;
        buf[(start + i) * 2] += v;
        buf[(start + i) * 2 + 1] += v * 0.9;
    }
}

/// Short bit-crushed burst for a hard cut.
fn glitch(buf: &mut [f32], at_seconds: f64, volume: f32, sample_rate: u32) {
    let start = (at_seconds * sample_rate as f64) as usize;
    let len = (0.14 * sample_rate as f64) as usize;
    let total = frames_len(buf);
    for i in 0..len {
        if start + i >= total {
            break;
        }
        let t = i as f32 / sample_rate as f32;
        let env = (1.0 - i as f32 / len as f32).powi(2);
        // Quantize a square wave to a few levels for the crushed edge.
        let square: f32 = if (t * 940.0).fract() < 0.5 { 1.0 } else { -1.0 };
        let stepped = (square * 3.0).round() / 3.0;
        let v = stepped * env * volume;
        buf[(start + i) * 2] += v;
        buf[(start + i) * 2 + 1] += v * 0.85;
    }
}

/// Sub-bass drop that lands under a cut.
fn sub_drop(buf: &mut [f32], at_seconds: f64, volume: f32, sample_rate: u32) {
    let start = (at_seconds * sample_rate as f64) as usize;
    let len = (0.9 * sample_rate as f64) as usize;
    let total = frames_len(buf);
    for i in 0..len {
        if start + i >= total {
            break;
        }
        let t = i as f64 / sample_rate as f64;
        let env = (-t * 3.4).exp();
        let freq = 92.0 - t * 46.0;
        let s = (freq * t * std::f64::consts::TAU).sin() * env * volume as f64;
        buf[(start + i) * 2] += s as f32;
        buf[(start + i) * 2 + 1] += s as f32;
    }
}

/// Decodes a PCM16 WAV file and mixes it at the given frame offset.
///
/// A missing or undecodable file keeps the slot silent; a file whose declared
/// sample rate differs from the plan is an input-contract violation, never an
/// implicit resample.
fn mix_wav(buf: &mut [f32], path: &str, delay_frames: u32, volume: f32, plan: &AudioPlan) -> Result<(), Error> {
    let Ok(bytes) = std::fs::read(path) else {
        // The narration slot is optional input; a missing file stays silent.
        return Ok(());
    };
    let Some(wav) = parse_wav_pcm16(&bytes) else {
        return Ok(());
    };
    if wav.sample_rate != plan.sample_rate {
        return Err(Error::invalid_input(format!(
            "narration {path} is {} Hz but the plan is {} Hz, no implicit resample",
            wav.sample_rate, plan.sample_rate
        )));
    }
    let start = (delay_frames as f64 / plan.fps as f64 * plan.sample_rate as f64) as usize;
    let total = frames_len(buf);
    for (i, frame) in wav.frames.iter().enumerate() {
        let at = start + i;
        if at >= total {
            break;
        }
        buf[at * 2] += frame[0] * volume;
        buf[at * 2 + 1] += frame[1] * volume;
    }
    Ok(())
}
